def min_cost_to_make_white(n, m, rectangles):
    # Initialize a 2D array to keep track of the number of black cells in each subgrid
    grid = [[0] * (n + 1) for _ in range(n + 1)]

    # Apply the 2D difference array technique to mark black cells
    for x1, y1, x2, y2 in rectangles:
        grid[x1][y1] += 1
        if x2 + 1 <= n:
            grid[x2 + 1][y1] -= 1
        if y2 + 1 <= n:
            grid[x1][y2 + 1] -= 1
        if x2 + 1 <= n and y2 + 1 <= n:
            grid[x2 + 1][y2 + 1] += 1

    # Compute the prefix sum to get the actual number of black cells in each cell
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            grid[i][j] += grid[i - 1][j] + grid[i][j - 1] - grid[i - 1][j - 1]

    # Function to calculate the cost of coloring a rectangle white
    def cost(h, w):
        return min(h, w)

    # Initialize the total cost
    total_cost = 0

    # Iterate over all possible subgrid sizes
    for h in range(1, n + 1):
        for w in range(1, n + 1):
            # Check if the subgrid is completely white
            is_white = True
            for i in range(h, n + 1):
                for j in range(w, n + 1):
                    if grid[i][j] - grid[i - h][j] - grid[i][j - w] + grid[i - h][j - w] > 0:
                        is_white = False
                        break
                if not is_white:
                    break
            if is_white:
                total_cost += cost(h, w)

    return total_cost

