def min_cost_to_make_white(n, m, rectangles):
    events = []
    for x1, y1, x2, y2 in rectangles:
        events.append((x1, 0, y1, y2))  # 0 for start of rectangle
        events.append((x2 + 1, 1, y1, y2))  # 1 for end of rectangle

    events.sort()

    active_intervals = []
    total_cost = 0
    last_x = 1

    for x, typ, y1, y2 in events:
        if active_intervals:
            total_cost += (x - last_x) * min_length(active_intervals)

        if typ == 0:
            active_intervals.append((y1, y2))
        else:
            active_intervals.remove((y1, y2))

        last_x = x

    return total_cost

def min_length(intervals):
    if not intervals:
        return 0
    intervals.sort()
    merged = [intervals[0]]
    for current in intervals:
        last = merged[-1]
        if current[0] <= last[1]:
            merged[-1] = (last[0], max(last[1], current[1]))
        else:
            merged.append(current)
    return sum(y2 - y1 + 1 for y1, y2 in merged)

