def min_cost_to_paint_white(n, m, rectangles):
    # Initialize a 2D difference array to track changes in black/white status
    diff = [[0] * (n + 1) for _ in range(n + 1)]

    # Apply the difference array technique to mark black rectangles
    for x1, y1, x2, y2 in rectangles:
        diff[x1][y1] += 1
        if x2 + 1 <= n:
            diff[x2 + 1][y1] -= 1
        if y2 + 1 <= n:
            diff[x1][y2 + 1] -= 1
        if x2 + 1 <= n and y2 + 1 <= n:
            diff[x2 + 1][y2 + 1] += 1

    # Calculate the prefix sum to determine the actual black/white status
    black = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            black[i][j] = diff[i][j]
            if i > 1:
                black[i][j] += black[i - 1][j]
            if j > 1:
                black[i][j] += black[i][j - 1]
            if i > 1 and j > 1:
                black[i][j] -= black[i - 1][j - 1]

    # Calculate the cost to paint the whole grid white
    total_cost = 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if black[i][j] > 0:
                # Find the maximum size rectangle that can be painted white at (i, j)
                max_h = max_w = 0
                while i + max_h <= n and black[i + max_h][j] > 0:
                    max_h += 1
                while j + max_w <= n and all(black[i + k][j + max_w] > 0 for k in range(max_h)):
                    max_w += 1
                # Calculate the cost for this rectangle
                total_cost += min(max_h, max_w)
                # Mark this rectangle as painted
                for k in range(i, i + max_h):
                    for l in range(j, j + max_w):
                        black[k][l] = 0

    return total_cost

